async function request<T>(path:string, token:string, init:RequestInit = {}):Promise<T>{
 const headers = new Headers(init.headers);
 if(token) headers.set("Authorization", "Bearer "+token);
 if(init.body && !(init.body instanceof FormData)) headers.set("Content-Type","application/json");
 const response = await fetch(API+path,{...init,headers});
 if(!response.ok){let message = "Request failed ("+response.status+")";try{const body=await response.json();message=body.detail||message;}catch{}throw new Error(message);}
 if(response.status===204) return undefined as T;
 return response.json() as Promise<T>;
}
const dateText=(value?:string|null)=>value?new Date(value).toLocaleDateString(undefined,{day:"2-digit",month:"short",year:"numeric"}):"—";
const dateInput=(days:number)=>{const d=new Date();d.setDate(d.getDate()+days);return d.toISOString().slice(0,10);};
function Status({value}:{value:string}){return <span className={"status "+value.toLowerCase().replaceAll(" ","-").replaceAll("/","-")}>{value}</span>}
function Priority({value}:{value:string}){return <span className={"priority "+value.toLowerCase()}><i/>{value}</span>}
function Metric({icon,label,value,note}:{icon:ReactNode;label:string;value:string|number;note:string}){return <div className="metric-card"><div className="metric-top"><span className="metric-icon">{icon}</span></div><div className="metric-value">{value}</div><div className="metric-label">{label}</div><div className="metric-note">{note}</div></div>}
